// load-all-posts.js: lists every post from /feed.xml (generated by build.js, newest first).
fetch("/feed.xml")
  .then(res => res.text())
  .then(xml => {
    const doc = new DOMParser().parseFromString(xml, "application/xml");
    const postList = document.getElementById("all-posts-list");
    postList.innerHTML = "";

    doc.querySelectorAll("item").forEach(item => {
      const text = tag => item.querySelector(tag).textContent;
      const li = document.createElement("li");

      const a = document.createElement("a");
      a.href = new URL(text("link")).pathname;
      a.textContent = text("title");

      const date = document.createElement("div");
      date.className = "post-date";
      date.textContent = new Date(text("pubDate")).toLocaleDateString(undefined, { timeZone: "UTC" });

      const description = document.createElement("div");
      description.className = "post-description";
      description.textContent = text("description");

      li.append(a, date, description);
      postList.appendChild(li);
    });
  })
  .catch(error => {
    document.getElementById("all-posts-list").innerHTML = `<li>Error loading posts: ${error.message}</li>`;
  });
